    arr[i] = value
    _pv_save()


def _flatten(args):
    out = []
    for a in args:
        if isinstance(a, (list, tuple)):
            out.extend(a)
        else:
            out.append(a)
    return out


def _gv_slug(name):
    return "pyscript.pistoncore_global_" + "".join(
        ch if ch.isalnum() else "_" for ch in name.lstrip("@").lower())


def _gv(name):
