import datetime
import math
import random
import re
import urllib.parse

task.unique("pistoncore_snap")  # kill in-flight old version on redeploy
state.persist("pyscript.pistoncore_snap_state", default_value="idle")

# piston local variables (from the piston's define section). Declared values
# are the defaults; anything the piston has since set is restored from the
# persisted state entity so variables survive HA restarts and recompiles —
# webCoRE keeps piston variables in state, so this matches it.
pv = {'DoorsOpen': None, 'WindowsOpen': None, 'SystemStatus': None, 'DoorLeftUnlocked': None, 'Unlocked_By': None, 'string_Disarmed_By_Name': None, 'integer_Lock_Confirm_Wait': 40, 'integer_Speaker_Volum': 90}

# ORDER MATTERS (fixed 2026-07-30): the restore used to run ABOVE this line,
# so it wrote into a `pv` that did not exist yet — a NameError swallowed by
# the except, logged as a warning nobody reads — and then `pv = ...` would
# have overwritten it anyway. Persisted variables never survived a restart.
# Defaults first, saved values overlaid on top.
try:
    _saved = state.getattr("pyscript.pistoncore_snap_state") or {}
    for _k, _v in (_saved.get("vars") or {}).items():
        pv[_k] = _v
except Exception as _e:
    log.warning(f"[snap] could not restore variables: {_e}")
# global variable values, snapshotted at compile time (recompile refreshes).
# ALWAYS defined, even when empty (2026-07-30): _gv() in the runtime falls
# back to `gv.get(name)` whenever the persisted pyscript entity is missing —
# which is the NORMAL path on a fresh deploy, before any piston has written
# that global. Emitting `gv` conditionally meant an always-present helper
# depended on a sometimes-present variable; consistent today only by
# accident of how used_globals is collected. An empty dict costs nothing and
# turns a possible NameError into a missing key.
gv = {}
_index = 0
_device = None
_STATE_ENTITY = "pyscript.pistoncore_snap_state"
_ALARM_ENTITY = "alarm_control_panel.dev_panel"
# ── webCoRE expression runtime (band-editable: add functions here AND to
#    _FUNCTIONS in shim/compiler/expression.py). Semantics follow the engine's
#    dynamic typing: values coerce at evaluation time, never at compile time.


def _num(x, default=0):
    try:
        f = float(x)
        return int(f) if f == int(f) else f
    except (TypeError, ValueError):
        return default


def _int(x):
    return int(_num(x))


def _truthy(x):
    if x is None:
        return False
    if isinstance(x, str):
        return x.strip().lower() not in ("", "false", "0", "off", "no", "null",
                                          "unknown", "unavailable", "none")
    return bool(x)


def _both_numeric(a, b):
    try:
        float(a), float(b)
        return True
    except (TypeError, ValueError):
        return False


def _op(a, o, b):
    """webCoRE binary operator with runtime coercion: numeric when both sides
    are numeric, string behavior otherwise ('+' concatenates)."""
    numeric = _both_numeric(a, b)
    if o == "+":
        if numeric:
            return _num(a) + _num(b)
        return ("" if a is None else str(a)) + ("" if b is None else str(b))
    if o == "-":
        return _num(a) - _num(b)
    if o == "adj":
        # ADJACENCY: two operands written next to each other with no operator.
        # The engine resolves it from the VALUES, not from the source text —
        # numbers multiply, anything else concatenates. Compiling it to "*"
        # coerced two strings to 0 and destroyed every accumulated report.
        if numeric:
            return _num(a) * _num(b)
        return ("" if a is None else str(a)) + ("" if b is None else str(b))
    if o == "*":
        return _num(a) * _num(b)
    if o in ("/",):
        d = _num(b)
        return _num(a) / d if d else 0
    if o == "\\":
        d = _num(b)
        return int(_num(a) // d) if d else 0
    if o == "%":
        d = _num(b)
        return _num(a) % d if d else 0
    if o == "**":
        return _num(a) ** _num(b)
    if o in ("==",):
        if numeric:
            return _num(a) == _num(b)
        return str(a).strip().lower() == str(b).strip().lower()
    if o in ("!=", "<>"):
        return not _op(a, "==", b)
    if o == ">":
        return _num(a) > _num(b) if numeric else str(a) > str(b)
    if o == "<":
        return _num(a) < _num(b) if numeric else str(a) < str(b)
    if o == ">=":
        return _num(a) >= _num(b) if numeric else str(a) >= str(b)
    if o == "<=":
        return _num(a) <= _num(b) if numeric else str(a) <= str(b)
    if o == "&&":
        return _truthy(a) and _truthy(b)
    if o == "||":
        return _truthy(a) or _truthy(b)
    if o == "^^":
        return _truthy(a) != _truthy(b)
    if o == "!&":
        return not (_truthy(a) and _truthy(b))
    if o == "!|":
        return not (_truthy(a) or _truthy(b))
    if o == "!^":
        return _truthy(a) == _truthy(b)
    if o == "&":
        return _int(a) & _int(b)
    if o == "|":
        return _int(a) | _int(b)
    if o == "^":
        return _int(a) ^ _int(b)
    if o == "<<":
        return _int(a) << _int(b)
    if o == ">>":
        return _int(a) >> _int(b)
    log.warning(f"unsupported operator {o}")
    return None


