    """The NAME of the device that woke this piston, not its entity id.

    webCoRE's $currentEventDevice is the device label a user recognises. This
    band was returning the raw entity id (binary_sensor.hall_motion) where the
    YAML band returned the friendly name, so the same piston read differently
    depending on which band it landed on.

    Falls back to the entity id when a device has no friendly name — better a
    usable id than an empty message.
    """
    try:
        return (state.getattr(str(entity_id)) or {}).get(
            "friendly_name") or str(entity_id)
    except Exception:
        return str(entity_id)


def _piston_automations(auto_ids):
    """The entity_ids of another piston's automations, found at HA's runtime.

    Home Assistant derives an automation's entity_id from its alias and changes
    it if two collide, so it cannot be predicted at compile time. The `id:`
    PistonCore writes IS stable, and HA keeps it as an attribute — so the match
    happens on that.

    A piston can compile to SEVERAL automations: a statement carrying a wait
    gets its own, so does a throttled `remains_*` trigger, and so does each
    `was_*` watcher. Pausing only the first would leave the piston acting while
    it looked paused, so all of them are returned.
    """
    wanted = set(auto_ids or [])
    found = []
    for entity_id in state.names("automation"):
        try:
            if (state.getattr(entity_id) or {}).get("id") in wanted:
                found.append(entity_id)
        except Exception:
            continue
    return found


def _hs_keep(entity_id, value, keep):
    """Set hue OR saturation while preserving the other half.

    HA's `hs_color` is a [hue, saturation] PAIR — there is no hue-only or
    saturation-only service — so changing one means sending both. Sending a bare
    number is rejected outright, and sending a constant for the other half
    silently recolours the light: a soft pastel told "set hue to 120" comes back
    fully saturated.

    So the half that was not asked for is read back off the light. A light that
    is off, or has never been given a colour, reports no hs_color; [0, 100] is
    the fallback, applied only when there is genuinely nothing to preserve.
    """
    try:
        current = (state.getattr(str(entity_id)) or {}).get("hs_color")
    except Exception:
        current = None
    if not current or len(current) < 2:
        current = [0, 100]
    return [value, current[1]] if keep == "saturation" else [current[0], value]


# ── was_* watchers ─────────────────────────────────────────────────────────
# webCoRE's was_* asks "has this been true CONTINUOUSLY for T", which it
# answers by walking state history. last_changed cannot answer it for any
# predicate that stays true ACROSS a value change — a fridge going 11° -> 12°
# is still above 10, but last_changed restarts and the duration never
# accumulates. So the moment a predicate becomes true is recorded here.
#
# The record lives on the piston's OWN persisted state entity, alongside its
# variables, so it costs no extra entity in Home Assistant and survives a
# restart the same way the variables do.
_was_since = {}


def _was_restore():
    try:
        for _k, _v in (state.getattr(_STATE_ENTITY + ".was") or {}).items():
            _was_since[_k] = _v
    except Exception:
        pass


def _was_save():
    try:
        state.setattr(_STATE_ENTITY + ".was", dict(_was_since))
    except Exception as exc:
        log.warning(f"could not persist was_* timers: {exc}")


def _was_mark(slug, holding):
    """Watcher hook: called whenever a watched value changes."""
    if holding:
        if _was_since.get(slug) is None:
            _was_since[slug] = datetime.datetime.now().isoformat()
            _was_save()
    elif _was_since.get(slug) is not None:
        _was_since.pop(slug, None)
        _was_save()


def _was_held(slug, holding, ms, at_least=True):
    """True when the predicate holds NOW and has held for >= / < ms."""
    if not holding:
        return False
    since = _was_since.get(slug)
    if since is None:
        # Never seen becoming true: a fresh deploy, or a value that has not
        # changed since. Fail CLOSED rather than assume it always held.
        return False
    try:
        then = datetime.datetime.fromisoformat(str(since))
        elapsed = (datetime.datetime.now(then.tzinfo) - then).total_seconds() * 1000
    except Exception:
        return False
    return elapsed >= ms if at_least else elapsed < ms


