# Generated by PistonCore — piston "Good Morning ☀️" (snap)
# DO NOT EDIT — changes are overwritten on recompile. Template band: pyscript/2.x
# Routed to PyScript because:
#   - YAML band can't express it: function 'random()' has no HA template equivalent yet (add it to _JINJA_FUNCS, or this piston uses PyScript)

import datetime
import math
import random
import re
import urllib.parse

task.unique("pistoncore_snap")  # kill in-flight old version on redeploy
state.persist("pyscript.pistoncore_snap_state", default_value="idle")

# piston local variables (from the piston's define section). Declared values
# are the defaults; anything the piston has since set is restored from the
# persisted state entity so variables survive HA restarts and recompiles —
# webCoRE keeps piston variables in state, so this matches it.
pv = {'Speaker_Vol': 40}

# ORDER MATTERS (fixed 2026-07-30): the restore used to run ABOVE this line,
# so it wrote into a `pv` that did not exist yet — a NameError swallowed by
# the except, logged as a warning nobody reads — and then `pv = ...` would
# have overwritten it anyway. Persisted variables never survived a restart.
# Defaults first, saved values overlaid on top.
try:
    _saved = state.getattr("pyscript.pistoncore_snap_state") or {}
    for _k, _v in (_saved.get("vars") or {}).items():
        pv[_k] = _v
except Exception as _e:
    log.warning(f"[snap] could not restore variables: {_e}")
# global variable values, snapshotted at compile time (recompile refreshes).
# ALWAYS defined, even when empty (2026-07-30): _gv() in the runtime falls
# back to `gv.get(name)` whenever the persisted pyscript entity is missing —
# which is the NORMAL path on a fresh deploy, before any piston has written
# that global. Emitting `gv` conditionally meant an always-present helper
# depended on a sometimes-present variable; consistent today only by
# accident of how used_globals is collected. An empty dict costs nothing and
# turns a possible NameError into a missing key.
gv = {}
_index = 0
_device = None
_STATE_ENTITY = "pyscript.pistoncore_snap_state"
_ALARM_ENTITY = "alarm_control_panel.dev_panel"
# ── webCoRE expression runtime (band-editable: add functions here AND to
#    _FUNCTIONS in shim/compiler/expression.py). Semantics follow the engine's
#    dynamic typing: values coerce at evaluation time, never at compile time.


def _num(x, default=0):
    try:
        f = float(x)
        return int(f) if f == int(f) else f
    except (TypeError, ValueError):
        return default


def _int(x):
    return int(_num(x))


def _truthy(x):
    if x is None:
        return False
    if isinstance(x, str):
        return x.strip().lower() not in ("", "false", "0", "off", "no", "null",
                                          "unknown", "unavailable", "none")
    return bool(x)


def _both_numeric(a, b):
    try:
        float(a), float(b)
        return True
    except (TypeError, ValueError):
        return False


def _op(a, o, b):
    """webCoRE binary operator with runtime coercion: numeric when both sides
    are numeric, string behavior otherwise ('+' concatenates)."""
    numeric = _both_numeric(a, b)
    if o == "+":
        if numeric:
            return _num(a) + _num(b)
        return ("" if a is None else str(a)) + ("" if b is None else str(b))
    if o == "-":
        return _num(a) - _num(b)
    if o == "adj":
        # ADJACENCY: two operands written next to each other with no operator.
        # The engine resolves it from the VALUES, not from the source text —
        # numbers multiply, anything else concatenates. Compiling it to "*"
        # coerced two strings to 0 and destroyed every accumulated report.
        if numeric:
            return _num(a) * _num(b)
        return ("" if a is None else str(a)) + ("" if b is None else str(b))
    if o == "*":
        return _num(a) * _num(b)
    if o in ("/",):
        d = _num(b)
        return _num(a) / d if d else 0
    if o == "\\":
        d = _num(b)
        return int(_num(a) // d) if d else 0
    if o == "%":
        d = _num(b)
        return _num(a) % d if d else 0
    if o == "**":
        return _num(a) ** _num(b)
    if o in ("==",):
        if numeric:
            return _num(a) == _num(b)
        return str(a).strip().lower() == str(b).strip().lower()
    if o in ("!=", "<>"):
        return not _op(a, "==", b)
    if o == ">":
        return _num(a) > _num(b) if numeric else str(a) > str(b)
    if o == "<":
        return _num(a) < _num(b) if numeric else str(a) < str(b)
    if o == ">=":
        return _num(a) >= _num(b) if numeric else str(a) >= str(b)
    if o == "<=":
        return _num(a) <= _num(b) if numeric else str(a) <= str(b)
    if o == "&&":
        return _truthy(a) and _truthy(b)
    if o == "||":
        return _truthy(a) or _truthy(b)
    if o == "^^":
        return _truthy(a) != _truthy(b)
    if o == "!&":
        return not (_truthy(a) and _truthy(b))
    if o == "!|":
        return not (_truthy(a) or _truthy(b))
    if o == "!^":
        return _truthy(a) == _truthy(b)
    if o == "&":
        return _int(a) & _int(b)
    if o == "|":
        return _int(a) | _int(b)
    if o == "^":
        return _int(a) ^ _int(b)
    if o == "<<":
        return _int(a) << _int(b)
    if o == ">>":
        return _int(a) >> _int(b)
    log.warning(f"unsupported operator {o}")
    return None


# ── time helpers (webCoRE times are epoch milliseconds) ─────────────────────

def _now_ms():
    return int(datetime.datetime.now().timestamp() * 1000)


def _utc_ms():
    return int(datetime.datetime.now(datetime.timezone.utc)
               .replace(tzinfo=None).timestamp() * 1000)


def _sysdate(fmt):
    return datetime.datetime.now().strftime(fmt)


def _sysnum(part):
    now = datetime.datetime.now()
    if part == "hour12":
        return now.hour % 12 or 12
    if part == "dow":
        return (now.weekday() + 1) % 7  # webCoRE: Sunday = 0
    return getattr(now, part)


def _daytime_ms(h, m):
    now = datetime.datetime.now()
    return int(now.replace(hour=h, minute=m, second=0, microsecond=0)
               .timestamp() * 1000)


def _sun_ms(which):
    try:
        v = state.getattr("sun.sun").get(which)
        return int(datetime.datetime.fromisoformat(str(v)).timestamp() * 1000)
    except Exception:
        return None


def _to_dt(v):
    """epoch ms / iso string / datetime -> datetime."""
    if isinstance(v, datetime.datetime):
        return v
    n = _num(v, None)
    if n is not None and n > 10000000:
        return datetime.datetime.fromtimestamp(n / 1000)
    try:
        return datetime.datetime.fromisoformat(str(v))
    except (TypeError, ValueError):
        return datetime.datetime.now()


# ── function library ────────────────────────────────────────────────────────

def _fn_lower(s):
    return str(s or "").lower()


def _fn_upper(s):
    return str(s or "").upper()


def _fn_trim(s):
    return str(s or "").strip()


def _fn_left(s, n):
    return str(s or "")[:_int(n)]


def _fn_right(s, n):
    return str(s or "")[-_int(n):] if _int(n) else ""


def _fn_mid(s, start, length=None):
    s = str(s or "")
    start = _int(start)
    return s[start:start + _int(length)] if length is not None else s[start:]


def _fn_substring(s, start, length=None):
    return _fn_mid(s, start, length)


def _fn_replace(s, *pairs):
    s = str(s or "")
    for i in range(0, len(pairs) - 1, 2):
        s = s.replace(str(pairs[i]), str(pairs[i + 1]))
    return s


def _fn_concat(*args):
    return "".join("" if a is None else str(a) for a in args)


def _fn_contains(s, needle):
    return str(needle) in str(s or "")


def _fn_startswith(s, needle):
    return str(s or "").startswith(str(needle))


def _fn_endswith(s, needle):
    return str(s or "").endswith(str(needle))


def _fn_indexof(haystack, needle):
    if isinstance(haystack, (list, tuple)):
        for i, x in enumerate(haystack):
            if str(x) == str(needle):
                return i
        return -1
    return str(haystack or "").find(str(needle))


def _fn_length(s):
    return len(s) if isinstance(s, (list, tuple)) else len(str(s or ""))


def _fn_count(x):
    return len(x) if isinstance(x, (list, tuple)) else (_fn_length(x) and 1)


def _fn_arrayitem(index, arr):
    if not isinstance(arr, (list, tuple)):
        return None
    i = _int(index)
    return arr[i] if 0 <= i < len(arr) else None


def _fn_item(index, arr):
    return _fn_arrayitem(index, arr)


def _fn_string(x):
    return "" if x is None else str(x)


def _fn_format(fmt, *args):
    try:
        return str(fmt) % tuple(args)
    except (TypeError, ValueError):
        return str(fmt)


def _fn_sprintf(fmt, *args):
    return _fn_format(fmt, *args)


def _fn_int(x):
    return _int(x)


def _fn_integer(x):
    return _int(x)


def _fn_decimal(x):
    return float(_num(x))


def _fn_float(x):
    return float(_num(x))


def _fn_number(x):
    return _num(x)


def _fn_round(x, digits=0):
    r = round(float(_num(x)), _int(digits))
    return _int(r) if not _int(digits) else r


def _fn_floor(x):
    return math.floor(_num(x))


def _fn_ceil(x):
    return math.ceil(_num(x))


def _fn_abs(x):
    return abs(_num(x))


def _fn_min(*args):
    vals = [_num(a) for a in _flatten(args)]
    return min(vals) if vals else None


def _fn_max(*args):
    vals = [_num(a) for a in _flatten(args)]
    return max(vals) if vals else None


def _fn_sum(*args):
    return sum(_num(a) for a in _flatten(args))


def _fn_avg(*args):
    vals = [_num(a) for a in _flatten(args)]
    return sum(vals) / len(vals) if vals else 0


def _fn_median(*args):
    vals = sorted(_num(a) for a in _flatten(args))
    return vals[len(vals) // 2] if vals else 0


def _fn_power(x, p):
    return _num(x) ** _num(p)


def _fn_sqrt(x):
    return math.sqrt(_num(x))


def _fn_random(*args):
    nums = [a for a in args if _both_numeric(a, 0)]
    if len(args) == 0:
        return random.random()
    if len(args) == 1 and nums:
        return random.randint(0, _int(args[0]))
    if len(args) == 2 and len(nums) == 2:
        return random.randint(_int(args[0]), _int(args[1]))
    return random.choice(args)


def _fn_isempty(x):
    return x is None or str(x).strip() == ""


def _fn_coalesce(*args):
    for a in args:
        if not _fn_isempty(a):
            return a
    return None


def _fn_boolean(x):
    return _truthy(x)


def _fn_bool(x):
    return _truthy(x)


def _fn_isbetween(v, a, b):
    v, a, b = _num(v), _num(a), _num(b)
    # time-of-day coercion: bounds are ms-since-midnight but v is an epoch
    # timestamp (isBetween($now, time('04:00'), time('23:00'))) -> compare
    # v's time-of-day, matching the engine's cast-to-common-type behavior
    if v > 86400000 >= max(a, b):
        dt = _to_dt(v)
        v = (dt.hour * 3600 + dt.minute * 60 + dt.second) * 1000
    return a <= v <= b if a <= b else (v >= a or v <= b)


def _fn_time(v):
    """time('16:30') / time(epoch-ms) -> ms since midnight (webCoRE time)."""
    if _both_numeric(v, 0):
        dt = _to_dt(v)
        return (dt.hour * 3600 + dt.minute * 60 + dt.second) * 1000
    try:
        parts = str(v).replace("AM", "").replace("PM", "").strip().split(":")
        h, m = _int(parts[0]), _int(parts[1] if len(parts) > 1 else 0)
        s = _int(parts[2]) if len(parts) > 2 else 0
        if "PM" in str(v).upper() and h < 12:
            h += 12
        return (h * 3600 + m * 60 + s) * 1000
    except Exception:
        return 0


def _fn_date(v):
    dt = _to_dt(v)
    return int(dt.replace(hour=0, minute=0, second=0, microsecond=0)
               .timestamp() * 1000)


def _fn_datetime(v):
    return int(_to_dt(v).timestamp() * 1000)


def _fn_addseconds(v, s):
    return _fn_datetime(v) + _int(s) * 1000


def _fn_addminutes(v, m):
    return _fn_datetime(v) + _int(m) * 60000


def _fn_addhours(v, h):
    return _fn_datetime(v) + _int(h) * 3600000


def _fn_adddays(v, d):
    return _fn_datetime(v) + _int(d) * 86400000


_JAVA_FMT = [("EEEE", "%A"), ("EEE", "%a"), ("MMMM", "%B"), ("MMM", "%b"),
             ("yyyy", "%Y"), ("yy", "%y"), ("MM", "%m"), ("dd", "%d"),
             ("HH", "%H"), ("hh", "%I"), ("mm", "%M"), ("ss", "%S"),
             ("a", "%p"), ("h", "%I"), ("H", "%H"), ("d", "%d"), ("M", "%m")]


def _fn_formatdatetime(v, fmt="yyyy-MM-dd HH:mm:ss"):
    """Java SimpleDateFormat (webCoRE) -> strftime, common tokens only."""
    out = str(fmt)
    for j, p in _JAVA_FMT:
        out = out.replace(j, p)
    s = _to_dt(v).strftime(out)
    return s.replace(" 0", " ").lstrip("0") if out.startswith("%I") else s


def _fn_formatduration(ms, friendly=False, granularity="s", show_ms=False):
    total = _int(ms) // 1000
    h, rem = divmod(total, 3600)
    m, s = divmod(rem, 60)
    if granularity == "m":
        return f"{h:02d}:{m:02d}" if not friendly else f"{h}h {m}m"
    return f"{h:02d}:{m:02d}:{s:02d}" if not friendly else f"{h}h {m}m {s}s"


def _fn_age(entity_id):
    try:
        lc = state.getattr(str(entity_id)).get("last_changed")
        then = datetime.datetime.fromisoformat(str(lc))
        return int((datetime.datetime.now(then.tzinfo) - then)
                   .total_seconds() * 1000)
    except Exception:
        return None


def _dev_name(entity_id):
    """The NAME of the device that woke this piston, not its entity id.

    webCoRE's $currentEventDevice is the device label a user recognises. This
    band was returning the raw entity id (binary_sensor.hall_motion) where the
    YAML band returned the friendly name, so the same piston read differently
    depending on which band it landed on.

    Falls back to the entity id when a device has no friendly name — better a
    usable id than an empty message.
    """
    try:
        return (state.getattr(str(entity_id)) or {}).get(
            "friendly_name") or str(entity_id)
    except Exception:
        return str(entity_id)


def _piston_automations(auto_ids):
    """The entity_ids of another piston's automations, found at HA's runtime.

    Home Assistant derives an automation's entity_id from its alias and changes
    it if two collide, so it cannot be predicted at compile time. The `id:`
    PistonCore writes IS stable, and HA keeps it as an attribute — so the match
    happens on that.

    A piston can compile to SEVERAL automations: a statement carrying a wait
    gets its own, so does a throttled `remains_*` trigger, and so does each
    `was_*` watcher. Pausing only the first would leave the piston acting while
    it looked paused, so all of them are returned.
    """
    wanted = set(auto_ids or [])
    found = []
    for entity_id in state.names("automation"):
        try:
            if (state.getattr(entity_id) or {}).get("id") in wanted:
                found.append(entity_id)
        except Exception:
            continue
    return found


def _hs_keep(entity_id, value, keep):
    """Set hue OR saturation while preserving the other half.

    HA's `hs_color` is a [hue, saturation] PAIR — there is no hue-only or
    saturation-only service — so changing one means sending both. Sending a bare
    number is rejected outright, and sending a constant for the other half
    silently recolours the light: a soft pastel told "set hue to 120" comes back
    fully saturated.

    So the half that was not asked for is read back off the light. A light that
    is off, or has never been given a colour, reports no hs_color; [0, 100] is
    the fallback, applied only when there is genuinely nothing to preserve.
    """
    try:
        current = (state.getattr(str(entity_id)) or {}).get("hs_color")
    except Exception:
        current = None
    if not current or len(current) < 2:
        current = [0, 100]
    return [value, current[1]] if keep == "saturation" else [current[0], value]


# ── was_* watchers ─────────────────────────────────────────────────────────
# webCoRE's was_* asks "has this been true CONTINUOUSLY for T", which it
# answers by walking state history. last_changed cannot answer it for any
# predicate that stays true ACROSS a value change — a fridge going 11° -> 12°
# is still above 10, but last_changed restarts and the duration never
# accumulates. So the moment a predicate becomes true is recorded here.
#
# The record lives on the piston's OWN persisted state entity, alongside its
# variables, so it costs no extra entity in Home Assistant and survives a
# restart the same way the variables do.
_was_since = {}


def _was_restore():
    try:
        for _k, _v in (state.getattr(_STATE_ENTITY + ".was") or {}).items():
            _was_since[_k] = _v
    except Exception:
        pass


def _was_save():
    try:
        state.setattr(_STATE_ENTITY + ".was", dict(_was_since))
    except Exception as exc:
        log.warning(f"could not persist was_* timers: {exc}")


def _was_mark(slug, holding):
    """Watcher hook: called whenever a watched value changes."""
    if holding:
        if _was_since.get(slug) is None:
            _was_since[slug] = datetime.datetime.now().isoformat()
            _was_save()
    elif _was_since.get(slug) is not None:
        _was_since.pop(slug, None)
        _was_save()


def _was_held(slug, holding, ms, at_least=True):
    """True when the predicate holds NOW and has held for >= / < ms."""
    if not holding:
        return False
    since = _was_since.get(slug)
    if since is None:
        # Never seen becoming true: a fresh deploy, or a value that has not
        # changed since. Fail CLOSED rather than assume it always held.
        return False
    try:
        then = datetime.datetime.fromisoformat(str(since))
        elapsed = (datetime.datetime.now(then.tzinfo) - then).total_seconds() * 1000
    except Exception:
        return False
    return elapsed >= ms if at_least else elapsed < ms


# ── coverage-audit additions (2026-07-23) ──────────────────────────────────
# webCoRE functions that previously compiled in NEITHER band, i.e. any piston
# using one hard-failed. Group H of the audit (previousValue, previousAge,
# newer, older, isPistonPaused, setVariable) is deliberately NOT here: it needs
# attribute history / piston state Home Assistant doesn't keep, and every
# workaround would stop working the moment PistonCore is removed
# (Jeremy 2026-07-23) — left for later research.

# -- spellings/aliases of functions already above --
def _fn_ceiling(x):
    return _fn_ceil(x)


def _fn_pow(x, p):
    return _fn_power(x, p)


def _fn_sqr(x):
    n = _num(x)
    return n * n


def _fn_strlen(s):
    return _fn_length(s)


def _fn_size(x):
    return _fn_count(x)


def _fn_text(x):
    return _fn_string(x)


def _fn_title(s):
    return str(s or "").title()


def _fn_lastindexof(haystack, needle):
    if isinstance(haystack, (list, tuple)):
        found = -1
        for i, x in enumerate(haystack):
            if str(x) == str(needle):
                found = i
        return found
    return str(haystack or "").rfind(str(needle))


def _fn_ltrim(s):
    return str(s or "").lstrip()


def _fn_rtrim(s):
    return str(s or "").rstrip()


def _fn_trimleft(s):
    return _fn_ltrim(s)


def _fn_trimright(s):
    return _fn_rtrim(s)


# -- function spellings of operators (a > b already compiles natively) --
def _fn_if(cond, a, b=""):
    return a if _truthy(cond) else b


def _fn_not(x):
    return not _truthy(x)


def _fn_eq(a, b):
    if _both_numeric(a, b):
        return _num(a) == _num(b)
    return str(a).strip().lower() == str(b).strip().lower()


def _fn_gt(a, b):
    return _num(a) > _num(b) if _both_numeric(a, b) else str(a) > str(b)


def _fn_ge(a, b):
    return _num(a) >= _num(b) if _both_numeric(a, b) else str(a) >= str(b)


def _fn_lt(a, b):
    return _num(a) < _num(b) if _both_numeric(a, b) else str(a) < str(b)


def _fn_le(a, b):
    return _num(a) <= _num(b) if _both_numeric(a, b) else str(a) <= str(b)


# -- math --
def _fn_sin(x):
    return math.sin(_num(x))


def _fn_cos(x):
    return math.cos(_num(x))


def _fn_tan(x):
    return math.tan(_num(x))


def _fn_asin(x):
    try:
        return math.asin(_num(x))
    except ValueError:
        return None


def _fn_atan2(y, x):
    return math.atan2(_num(y), _num(x))


def _fn_log(x, base=None):
    n = _num(x)
    if n <= 0:
        return None
    return math.log(n) if base is None else math.log(n, _num(base))


def _fn_todegrees(x):
    return math.degrees(_num(x))


def _fn_toradians(x):
    return math.radians(_num(x))


# -- statistics --
def _fn_variance(*args):
    vals = [_num(a) for a in _flatten(args)]
    if len(vals) < 2:
        return 0
    mean = sum(vals) / len(vals)
    return sum((v - mean) ** 2 for v in vals) / len(vals)


def _fn_stdev(*args):
    return math.sqrt(_fn_variance(*args))


def _fn_sort(*args):
    vals = _flatten(args)
    if vals and all(_both_numeric(v, 0) for v in vals):
        return sorted(vals, key=_num)
    return sorted((str(v) for v in vals))


# -- date & time --
def _fn_addweeks(v, w):
    return _fn_datetime(v) + _int(w) * 604800000


def _fn_dateadd(v, amount, unit="d"):
    """dateAdd(date, amount, unit) - unit s/m/h/d/w, days by default."""
    u = str(unit or "d").strip().lower()[:1]
    mult = {"s": 1000, "m": 60000, "h": 3600000, "d": 86400000, "w": 604800000}
    return _fn_datetime(v) + _int(amount) * mult.get(u, 86400000)


def _fn_monthname(v=None):
    return _to_dt(_now_ms() if v is None else v).strftime("%B")


def _fn_weekdayname(v=None):
    return _to_dt(_now_ms() if v is None else v).strftime("%A")


def _fn_parsedatetime(s, fmt=None):
    """Date/time string -> epoch ms. ISO by default, or a Java pattern."""
    try:
        if fmt:
            pat = str(fmt)
            for j, p in _JAVA_FMT:
                pat = pat.replace(j, p)
            return int(datetime.datetime.strptime(str(s), pat).timestamp() * 1000)
        return int(datetime.datetime.fromisoformat(str(s)).timestamp() * 1000)
    except Exception:
        return None


def _fn_roundtimetominutes(v, minutes=1):
    """Round an epoch-ms time to the nearest N minutes."""
    step = max(1, _int(minutes)) * 60000
    return int(round(_fn_datetime(v) / step) * step)


def _fn_settzid(tzid):
    """webCoRE pins the piston's timezone; HA already runs in the configured
    local timezone, so this is accepted and otherwise inert."""
    return str(tzid or "")


# -- string / encoding --
def _fn_urlencode(s):
    return urllib.parse.quote(str("" if s is None else s), safe="")


def _fn_encodeuricomponent(s):
    return _fn_urlencode(s)


def _fn_matches(s, pattern):
    """Regex test (webCoRE matches -> boolean)."""
    try:
        return re.search(str(pattern), str("" if s is None else s)) is not None
    except re.error:
        return False


# -- temperature --
def _fn_fahrenheit(c):
    return _num(c) * 9.0 / 5.0 + 32


def _fn_celsius(f):
    return (_num(f) - 32) * 5.0 / 9.0


def _pv_setidx(name, index, value):
    """setVariable into an array element (webCoRE type[] variables) —
    auto-grows the list like the engine's sparse arrays."""
    arr = pv.get(name)
    if not isinstance(arr, list):
        arr = []
        pv[name] = arr
    i = _int(index)
    while len(arr) <= i:
        arr.append(None)
    arr[i] = value
    _pv_save()


def _flatten(args):
    out = []
    for a in args:
        if isinstance(a, (list, tuple)):
            out.extend(a)
        else:
            out.append(a)
    return out


def _gv_slug(name):
    return "pyscript.pistoncore_global_" + "".join(
        ch if ch.isalnum() else "_" for ch in name.lstrip("@").lower())


